1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useMemo, useRef, useState } from "react";
5	import type { Tag } from "@/types";
6	import styles from "./TagBar.module.css";
7	
8	/**
9	 * Tracks which edges of the horizontal-scroll tag row have content
10	 * past them, so the CSS can fade the appropriate edge(s). Returns
11	 * "none" when the row fits without scrolling, and "start" / "middle"
12	 * / "end" when it overflows — start = at the leftmost position
13	 * (only right edge has more), middle = both, end = scrolled to the
14	 * end (only left edge has more).
15	 */
16	function useScrollEdges(ref: React.RefObject<HTMLDivElement | null>) {
17	  const [edge, setEdge] = useState<"none" | "start" | "middle" | "end">("start");
18	
19	  useEffect(() => {
20	    const el = ref.current;
21	    if (!el) return;
22	
23	    const update = () => {
24	      // Re-read from the ref each call rather than relying solely on
25	      // the captured `el`. If the DOM element is detached between
26	      // listener registration and the next event, this stays safe
27	      // instead of dereferencing a node that's no longer in the tree.
28	      const current = ref.current;
29	      if (!current) return;
30	      // 1-px tolerance for sub-pixel scroll positions.
31	      if (current.scrollWidth <= current.clientWidth + 1) {
32	        setEdge("none");
33	        return;
34	      }
35	      const atStart = current.scrollLeft <= 1;
36	      const atEnd =
37	        current.scrollLeft + current.clientWidth >= current.scrollWidth - 1;
38	      if (atStart) setEdge("start");
39	      else if (atEnd) setEdge("end");
40	      else setEdge("middle");
41	    };
42	
43	    update();
44	    el.addEventListener("scroll", update, { passive: true });
45	    // Resize can change whether the row overflows at all.
46	    window.addEventListener("resize", update);
47	    return () => {
48	      el.removeEventListener("scroll", update);
49	      window.removeEventListener("resize", update);
50	    };
51	  }, [ref]);
52	
53	  return edge;
54	}
55	
56	interface Props {
57	  tags: Tag[];
58	  /** Active tag ids — these get the gold-stroke active state */
59	  activeIds?: string[];
60	  /** Base href for tag links (e.g., "/search") */
61	  basePath?: string;
62	  /** Existing search query to preserve when clicking tags */
63	  search?: string;
64	  /** Threshold below which the toggle button stays hidden */
65	  expandThreshold?: number;
66	}
67	
68	/**
69	 * Tag filter bar.
70	 *
71	 * Default: single-line horizontal scroll with a fade on the right edge.
72	 * Expanded: tags are grouped by their first letter (A, B, C...) so a
73	 * 500-tag taxonomy stays browseable. Each letter is a row with the
74	 * letter on the left and pills wrapping to the right.
75	 *
76	 * Color rules:
77	 *   - safe tag (isAdult = false)  -> green pill
78	 *   - adult tag (isAdult = true)  -> red pill
79	 *   - selected (active) tag       -> gold border, regardless
80	 */
81	export default function TagBar({
82	  tags,
83	  activeIds,
84	  basePath = "/search",
85	  search,
86	  expandThreshold = 12,
87	}: Props) {
88	  const [expanded, setExpanded] = useState(false);
89	  const activeSet = useMemo(() => new Set(activeIds ?? []), [activeIds]);
90	  const showToggle = tags.length > expandThreshold;
91	
92	  const allHref = search
93	    ? `${basePath}?search=${encodeURIComponent(search)}`
94	    : basePath;
95	
96	  const buildTagHref = (tagId: string) => {
97	    const params = new URLSearchParams();
98	    if (search) params.set("search", search);
99	    params.set("tagIds", tagId);
100	    return `${basePath}?${params.toString()}`;
101	  };
102	
103	  const sortedTags = useMemo(
104	    () => [...tags].sort((a, b) => a.name.localeCompare(b.name)),
105	    [tags],
106	  );
107	
108	  // Group expanded tags by first letter for browsability.
109	  const grouped = useMemo(() => {
110	    const map = new Map<string, Tag[]>();
111	    for (const tag of sortedTags) {
112	      const ch = tag.name.charAt(0);
113	      const key = ch ? (/[a-z]/i.test(ch) ? ch.toUpperCase() : "#") : "#";
114	      const list = map.get(key) ?? [];
115	      list.push(tag);
116	      map.set(key, list);
117	    }
118	    return Array.from(map.entries()).sort(([a], [b]) => {
119	      if (a === "#") return 1;
120	      if (b === "#") return -1;
121	      return a.localeCompare(b);
122	    });
123	  }, [sortedTags]);
124	
125	  if (tags.length === 0) return null;
126	
127	  if (expanded) {
128	    return (
129	      <div className={styles.wrapper}>
130	        <div className={styles.collapseRow}>
131	          <button
132	            type="button"
133	            onClick={() => setExpanded(false)}
134	            className={styles.toggle}
135	            // Explicit boolean — `aria-expanded` without a value
136	            // renders as the empty string, which some screen readers
137	            // misinterpret. The collapsed-row button below uses
138	            // `aria-expanded={false}` so this mirror is consistent.
139	            aria-expanded={true}
140	          >
141	            Collapse
142	            <Chevron open />
143	          </button>
144	        </div>
145	
146	        <div className={styles.expanded}>
147	          {/* "All" stays at the top */}
148	          <div className={styles.letterGroup}>
149	            <span className={styles.letter} aria-hidden>·</span>
150	            <div className={styles.letterPills}>
151	              <Link
152	                href={allHref}
153	                className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
154	              >
155	                All
156	              </Link>
157	            </div>
158	          </div>
159	
160	          {grouped.map(([letter, letterTags]) => (
161	            <div key={letter} className={styles.letterGroup}>
162	              <span className={styles.letter}>{letter}</span>
163	              <div className={styles.letterPills}>
164	                {letterTags.map((tag) => (
165	                  <Pill
166	                    key={tag.id}
167	                    tag={tag}
168	                    href={buildTagHref(tag.id)}
169	                    active={activeSet.has(tag.id)}
170	                  />
171	                ))}
172	              </div>
173	            </div>
174	          ))}
175	        </div>
176	      </div>
177	    );
178	  }
179	
180	  // Collapsed (default): single horizontal-scroll row.
181	  return <CollapsedRow
182	    sortedTags={sortedTags}
183	    allHref={allHref}
184	    activeSet={activeSet}
185	    buildTagHref={buildTagHref}
186	    showToggle={showToggle}
187	    onExpand={() => setExpanded(true)}
188	  />;
189	}
190	
191	function CollapsedRow({
192	  sortedTags,
193	  allHref,
194	  activeSet,
195	  buildTagHref,
196	  showToggle,
197	  onExpand,
198	}: {
199	  sortedTags: Tag[];
200	  allHref: string;
201	  activeSet: Set<string>;
202	  buildTagHref: (id: string) => string;
203	  showToggle: boolean;
204	  onExpand: () => void;
205	}) {
206	  const listRef = useRef<HTMLDivElement>(null);
207	  // Drives the data-scroll attribute on the list, which the CSS
208	  // uses to pick a mask-image (left fade / right fade / both /
209	  // none) per the row's current scroll position.
210	  const edge = useScrollEdges(listRef);
211	
212	  return (
213	    <div className={styles.wrapper}>
214	      <div className={styles.row}>
215	        <div ref={listRef} className={styles.list} data-scroll={edge}>
216	          <Link
217	            href={allHref}
218	            className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
219	          >
220	            All
221	          </Link>
222	          {sortedTags.map((tag) => (
223	            <Pill
224	              key={tag.id}
225	              tag={tag}
226	              href={buildTagHref(tag.id)}
227	              active={activeSet.has(tag.id)}
228	            />
229	          ))}
230	        </div>
231	
232	        {showToggle && (
233	          <button
234	            type="button"
235	            onClick={onExpand}
236	            className={styles.toggle}
237	            aria-expanded={false}
238	          >
239	            All tags
240	            <Chevron open={false} />
241	          </button>
242	        )}
243	      </div>
244	    </div>
245	  );
246	}
247	
248	function Pill({
249	  tag,
250	  href,
251	  active,
252	}: {
253	  tag: Tag;
254	  href: string;
255	  active: boolean;
256	}) {
257	  const variant = tag.isAdult ? styles.pillAdult : styles.pillSafe;
258	  const activeCls = active ? styles.pillActive : "";
259	  return (
260	    <Link
261	      href={href}
262	      className={`${styles.pill} ${variant} ${activeCls}`}
263	      title={tag.isAdult ? `${tag.name} (adult)` : tag.name}
264	    >
265	      {tag.name}
266	    </Link>
267	  );
268	}
269	
270	function Chevron({ open }: { open: boolean }) {
271	  return (
272	    <svg
273	      className={`${styles.chevron} ${open ? styles.chevronOpen : ""}`}
274	      viewBox="0 0 24 24"
275	      fill="none"
276	      stroke="currentColor"
277	      strokeWidth="2"
278	      strokeLinecap="round"
279	      strokeLinejoin="round"
280	      aria-hidden="true"
281	      suppressHydrationWarning
282	    >
283	      <polyline points="6 9 12 15 18 9" />
284	    </svg>
285	  );
286	}
