21	export const metadata: Metadata = {
22	  title: "Browse Stories & Series",
23	  description:
24	    "Browse the latest dark erotica and adult short fiction on Lucifer's Diary — new sex stories, slow-burn series, plus the most-liked and most-read tales.",
25	  alternates: { canonical: "/browse" },
26	};
