28	export default async function BrowsePage() {
29	  // Concurrent fetches with graceful fallback if any one fails — the
30	  // page shouldn't 500 because Author's Choice is empty, for example.
31	  const [tags, latestStories, latestSeries, mostLiked, mostRead, authorsChoice] =
32	    await Promise.all([
33	      getTags().catch(() => []),
34	      getLatestStories().catch(() => []),
35	      getLatestSeries().catch(() => []),
36	      getMostLiked().catch(() => []),
37	      getMostRead().catch(() => []),
38	      getAuthorsChoice().catch(() => []),
39	    ]);
40	
41	  const sections = [
42	    {
43	      key: "latest-stories",
44	      title: "New Stories",
45	      items: latestStories,
46	      type: "story" as const,
47	    },
48	    {
49	      key: "latest-series",
50	      title: "New Series",
51	      items: latestSeries,
52	      type: "series" as const,
53	    },
54	    {
55	      key: "most-liked",
56	      title: "Most Liked",
57	      items: mostLiked,
58	      type: "homepage" as const,
59	    },
60	    {
61	      key: "most-read",
62	      title: "Most Read",
63	      items: mostRead,
64	      type: "homepage" as const,
65	    },
66	    {
67	      key: "authors-choice",
68	      title: "Author's Choice",
69	      items: authorsChoice,
70	      type: "homepage" as const,
71	    },
72	  ];
73	
74	  const isEmpty = sections.every((s) => s.items.length === 0);
75	
76	  return (
77	    <>
78	      <SiteHeader />
79	      <div className={styles.page}>
80	        {/* Visually-hidden page heading — keeps the browse view the
81	            clean rails layout it has always been while still giving
82	            the page a single <h1> for accessibility + SEO. */}
83	        <h1 className={styles.srOnly}>Browse dark erotica stories &amp; series</h1>
84	        <TagBar tags={tags} basePath="/search" />
85	
86	        <main id="main" tabIndex={-1} className={styles.main}>
87	          {/* Scroll-position-driven resume row (backend-backed), then
88	              the series-level continue row. Both self-hide when empty. */}
89	          <ResumeReadingRow />
90	          <ContinueReadingRow />
91	
92	          {/* Personalized row — renders only for logged-in readers. */}
93	          <RecommendationsRow />
94	
95	          {isEmpty ? (
96	            <p className={styles.empty}>No stories yet.</p>
97	          ) : (
98	            sections
99	              .filter((s) => s.items.length > 0)
100	              .map((section) => (
101	                <ExpandableSection
102	                  key={section.key}
103	                  title={section.title}
104	                  expandable={section.items.length > 4}
105	                >
106	                  {section.type === "story" &&
107	                    section.items.map((item) => (
108	                      <StoryCard key={item.id} story={item} />
109	                    ))}
110	                  {section.type === "series" &&
111	                    section.items.map((item) => (
112	                      <SeriesCard key={item.id} series={item} />
113	                    ))}
114	                  {section.type === "homepage" &&
115	                    section.items.map((item) => (
116	                      <HomepageItem key={item.id} item={item} />
117	                    ))}
118	                </ExpandableSection>
119	              ))
120	          )}
121	        </main>
122	      </div>
123	    </>
124	  );
125	}
126	
127	function HomepageItem({ item }: { item: HomepageCardItem }) {
128	  if (item.type === "story") return <StoryCard story={item} />;
129	  return <ChapterCard chapter={item} />;
130	}
