1	import type { Metadata } from "next";
2	import CardGrid from "@/components/CardGrid";
3	import { SeriesCard } from "@/components/SeriesCard";
4	import SiteHeader from "@/components/SiteHeader";
5	import StoryCard from "@/components/StoryCard";
6	import TagBar from "@/components/TagBar";
7	import { getSeriesList, getStories, getTags } from "@/lib/api";
8	import styles from "./page.module.css";
9	
10	// Static metadata is fine — the page reads `searchParams` at request
11	// time, but the title / description / canonical are constant. Title
12	// is just "Search" so the root layout's `%s — Lucifer's Diary`
13	// template builds the full string (previous version baked the suffix
14	// into the title and ended up duplicated under the template).
15	const SEARCH_DESCRIPTION =
16	  "Search published stories and series on Lucifer's Diary by keyword or tag.";
17	
18	export const metadata: Metadata = {
19	  title: "Search",
20	  description: SEARCH_DESCRIPTION,
21	  // Canonical pinned to the bare /search — query-string variants
22	  // (?search=…&tagIds=…) consolidate here in Google's index instead
23	  // of producing one shadow URL per filter combination.
24	  alternates: { canonical: "/search" },
25	  openGraph: {
26	    type: "website",
27	    title: "Search",
28	    description: SEARCH_DESCRIPTION,
29	    url: "/search",
30	  },
31	  twitter: {
32	    card: "summary_large_image",
33	    title: "Search",
34	    description: SEARCH_DESCRIPTION,
35	  },
36	};
37	
38	export default async function SearchPage({
39	  searchParams,
40	}: {
41	  searchParams: Promise<{ search?: string; tagIds?: string | string[] }>;
42	}) {
43	  const params = await searchParams;
44	  const search = params.search?.trim() || undefined;
45	  const tagIdsRaw = params.tagIds;
46	  const tagIds = tagIdsRaw
47	    ? Array.isArray(tagIdsRaw)
48	      ? tagIdsRaw
49	      : [tagIdsRaw]
50	    : undefined;
51	
52	  const [tags, storiesRes, seriesRes] = await Promise.all([
53	    getTags().catch(() => []),
54	    getStories({ search, tagIds, limit: 60 }).catch(() => ({
55	      data: [],
56	      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
57	    })),
58	    getSeriesList({ search, tagIds, limit: 60 }).catch(() => ({
59	      data: [],
60	      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
61	    })),
62	  ]);
63	
64	  const stories = storiesRes.data;
65	  const seriesList = seriesRes.data;
66	  const totalCount = stories.length + seriesList.length;
67	
68	  const subtitle = describeSearch({ search, tagIds, tags, totalCount });
69	
70	  return (
71	    <>
72	      <SiteHeader />
73	      <div className={styles.page}>
74	        <div className={styles.intro}>
75	        <h2 className={styles.title}>Search</h2>
76	        <p className={styles.subtitle}>{subtitle}</p>
77	      </div>
78	
79	      <TagBar
80	        tags={tags}
81	        activeIds={tagIds}
82	        basePath="/search"
83	        search={search}
84	      />
85	
86	
87	      <main id="main" tabIndex={-1} className={styles.main}>
88	        {totalCount === 0 ? (
89	          <p className={styles.empty}>No stories match.</p>
90	        ) : (
91	          <>
92	            {stories.length > 0 && (
93	              <section className={styles.section}>
94	                <h3 className={styles.sectionTitle}>
95	                  Stories &middot; {stories.length}
96	                </h3>
97	                <CardGrid>
98	                  {stories.map((s) => (
99	                    <StoryCard key={s.id} story={s} />
100	                  ))}
101	                </CardGrid>
102	              </section>
103	            )}
104	            {seriesList.length > 0 && (
105	              <section className={styles.section}>
106	                <h3 className={styles.sectionTitle}>
107	                  Series &middot; {seriesList.length}
108	                </h3>
109	                <CardGrid>
110	                  {seriesList.map((sr) => (
111	                    <SeriesCard key={sr.id} series={sr} />
112	                  ))}
113	                </CardGrid>
114	              </section>
115	            )}
116	          </>
117	        )}
118	        </main>
119	      </div>
120	    </>
121	  );
122	}
123	
124	function describeSearch({
125	  search,
126	  tagIds,
127	  tags,
128	  totalCount,
129	}: {
130	  search?: string;
131	  tagIds?: string[];
132	  tags: { id: string; name: string }[];
133	  totalCount: number;
134	}): string {
135	  const parts: string[] = [];
136	  if (search) parts.push(`for "${search}"`);
137	  if (tagIds && tagIds.length > 0) {
138	    const names = tagIds
139	      .map((id) => tags.find((t) => t.id === id)?.name)
140	      .filter((n): n is string => !!n);
141	    if (names.length > 0) {
142	      parts.push(`tagged ${names.map((n) => `#${n}`).join(", ")}`);
143	    }
144	  }
145	  if (parts.length === 0) {
146	    return totalCount === 1
147	      ? "1 published piece"
148	      : `${totalCount} published pieces`;
149	  }
150	  return `${totalCount} ${totalCount === 1 ? "result" : "results"} ${parts.join(" ")}`;
151	}
