1	import { notFound } from "next/navigation";
2	import type { Metadata } from "next";
3	import CardGrid from "@/components/CardGrid";
4	import { SeriesCard } from "@/components/SeriesCard";
5	import SiteHeader from "@/components/SiteHeader";
6	import StoryCard from "@/components/StoryCard";
7	import { ApiError, getSeriesList, getStories, getTagBySlug } from "@/lib/api";
8	import { SITE_NAME, SITE_URL } from "@/lib/site";
9	import styles from "../../search/page.module.css";
10	
11	export async function generateMetadata({
12	  params,
13	}: {
14	  params: Promise<{ slug: string }>;
15	}): Promise<Metadata> {
16	  const { slug } = await params;
17	  try {
18	    const tag = await getTagBySlug(slug);
19	    // Keyword-led title (runs through the `%s — Lucifer's Diary`
20	    // template) + a description that names the tag alongside the
21	    // genre terms readers actually search for.
22	    const description = `Read ${tag.name} erotica and adult sex stories on ${SITE_NAME} — long-form tales and slow-burn series for readers who like it dark.`;
23	    return {
24	      title: `${tag.name} Erotica & Sex Stories`,
25	      description,
26	      alternates: { canonical: `/tag/${tag.slug}` },
27	      openGraph: {
28	        title: `${tag.name} Erotica & Sex Stories — ${SITE_NAME}`,
29	        description,
30	        url: `${SITE_URL}/tag/${tag.slug}`,
31	      },
32	    };
33	  } catch {
34	    return { title: "Tag not found" };
35	  }
36	}
