38	export default async function TagPage({
39	  params,
40	}: {
41	  params: Promise<{ slug: string }>;
42	}) {
43	  const { slug } = await params;
44	
45	  let tag;
46	  try {
47	    tag = await getTagBySlug(slug);
48	  } catch (e) {
49	    if (e instanceof ApiError && e.status === 404) notFound();
50	    throw e;
51	  }
52	
53	  const [storiesRes, seriesRes] = await Promise.all([
54	    getStories({ tagIds: [tag.id], limit: 60 }).catch(() => ({
55	      data: [],
56	      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
57	    })),
58	    getSeriesList({ tagIds: [tag.id], limit: 60 }).catch(() => ({
59	      data: [],
60	      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
61	    })),
62	  ]);
63	
64	  const stories = storiesRes.data;
65	  const seriesList = seriesRes.data;
66	  const totalCount = stories.length + seriesList.length;
67	
68	  return (
69	    <>
70	      <SiteHeader />
71	      <div className={styles.page}>
72	        <div className={styles.intro}>
73	        <h1 className={styles.title}>
74	          <span style={{ color: "var(--gold)", fontStyle: "italic" }}>#</span>
75	          {tag.name}
76	          {tag.isAdult && (
77	            <span
78	              style={{
79	                marginLeft: 12,
80	                fontFamily: "var(--font-ui)",
81	                fontSize: 11,
82	                fontWeight: 600,
83	                letterSpacing: "0.12em",
84	                textTransform: "uppercase",
85	                color: "var(--like)",
86	                border: "1px solid var(--like)",
87	                padding: "2px 10px",
88	                borderRadius: "var(--radius-pill)",
89	                verticalAlign: "middle",
90	              }}
91	            >
92	              Adult
93	            </span>
94	          )}
95	        </h1>
96	        <p className={styles.subtitle}>
97	          {totalCount === 0
98	            ? "Nothing tagged with this yet."
99	            : `${totalCount} ${tag.name} ${totalCount === 1 ? "story" : "stories"} & series — dark erotica on ${SITE_NAME}.`}
100	        </p>
101	      </div>
102	
103	      <main id="main" tabIndex={-1} className={styles.main}>
104	        {totalCount === 0 ? (
105	          <p className={styles.empty}>Nothing yet.</p>
106	        ) : (
107	          <>
108	            {stories.length > 0 && (
109	              <section className={styles.section}>
