17	   left (← more tags), "middle" fades both, "none" disables the
18	   mask when the row fits without scrolling. */
19	.list {
20	  display: flex;
21	  gap: 8px;
22	  overflow-x: auto;
23	  scrollbar-width: none;
24	  flex: 1;
25	  padding: 4px 0;
26	  transition:
27	    -webkit-mask-image var(--transition-fast),
28	    mask-image var(--transition-fast);
29	}
30	.list[data-scroll="start"] {
31	  -webkit-mask-image: linear-gradient(
32	    to right,
33	    var(--bg) 92%,
34	    transparent 100%
35	  );
36	  mask-image: linear-gradient(
37	    to right,
38	    var(--bg) 92%,
39	    transparent 100%
40	  );
41	}
42	.list[data-scroll="middle"] {
43	  -webkit-mask-image: linear-gradient(
44	    to right,
45	    transparent 0%,
46	    var(--bg) 8%,
47	    var(--bg) 92%,
48	    transparent 100%
49	  );
50	  mask-image: linear-gradient(
51	    to right,
52	    transparent 0%,
53	    var(--bg) 8%,
54	    var(--bg) 92%,
55	    transparent 100%
56	  );
57	}
58	.list[data-scroll="end"] {
59	  -webkit-mask-image: linear-gradient(
60	    to right,
61	    transparent 0%,
62	    var(--bg) 8%
63	  );
64	  mask-image: linear-gradient(
65	    to right,
66	    transparent 0%,
67	    var(--bg) 8%
68	  );
69	}
70	.list::-webkit-scrollbar {
71	  display: none;
72	}
73	
74	/* Expanded mode is a column of letter groups, each with its own pills */
75	.expanded {
76	  display: flex;
77	  flex-direction: column;
78	  gap: 16px;
79	  padding: 8px 0;
80	}
81	
82	.letterGroup {
83	  display: flex;
84	  gap: 16px;
85	  align-items: flex-start;
86	}
87	
88	.letter {
89	  flex-shrink: 0;
90	  width: 28px;
91	  font-family: var(--font-display);
92	  font-size: 18px;
93	  font-weight: 600;
94	  color: var(--gold);
95	  line-height: 1.4;
96	  user-select: none;
97	}
98	
99	.letterPills {
100	  display: flex;
101	  flex-wrap: wrap;
102	  gap: 8px;
103	  flex: 1;
104	  min-width: 0;
105	}
106	
107	/* Filter pill — base. By default neutral; safe + adult variants
108	   add color via the .pillSafe / .pillAdult modifiers. Active state
109	   is a gold border, regardless of safe/adult. */
110	.pill {
111	  font-family: var(--font-ui);
112	  font-size: var(--fs-tag);
113	  font-weight: 500;
114	  letter-spacing: var(--tracking-tag);
115	  text-transform: uppercase;
116	  color: var(--text-muted);
117	  background: transparent;
118	  padding: 6px 14px;
119	  border-radius: var(--radius-pill);
120	  border: 1px solid var(--border-line);
121	  text-decoration: none;
122	  white-space: nowrap;
123	  flex-shrink: 0;
124	  transition:
125	    color var(--transition-fast),
126	    border-color var(--transition-fast),
127	    background var(--transition-fast);
128	}
129	.pill:hover {
130	  color: var(--text);
131	  border-color: var(--border-line-hover);
132	}
133	
134	.pillSafe {
135	  color: var(--published);
136	  background: var(--published-tint);
137	  border-color: rgba(111, 207, 151, 0.32);
138	}
139	.pillSafe:hover {
140	  color: var(--published);
141	  border-color: rgba(111, 207, 151, 0.55);
142	}
143	
144	.pillAdult {
145	  color: var(--like);
146	  background: var(--like-tint);
147	  border-color: rgba(224, 123, 123, 0.32);
148	}
149	.pillAdult:hover {
150	  color: var(--like);
151	  border-color: rgba(224, 123, 123, 0.55);
152	}
153	
154	/* Active = selected. Gold stroke regardless of safe/adult. */
155	.pillActive {
156	  border-color: var(--gold);
157	}
158	.pillActive:hover {
159	  border-color: var(--gold);
160	}
161	
162	/* Toggle button at the end of the row */
163	.toggle {
164	  flex-shrink: 0;
165	  display: inline-flex;
166	  align-items: center;
167	  gap: 6px;
168	  padding: 6px 12px;
169	  border: 1px solid var(--border-line);
170	  border-radius: var(--radius-pill);
171	  background: var(--bg-surface);
172	  color: var(--text-muted);
173	  font-family: var(--font-ui);
174	  font-size: var(--fs-tag);
175	  font-weight: 500;
176	  letter-spacing: var(--tracking-tag);
177	  text-transform: uppercase;
178	  cursor: pointer;
179	  transition:
180	    color var(--transition-fast),
181	    border-color var(--transition-fast),
182	    background var(--transition-fast);
183	}
184	.toggle:hover {
185	  color: var(--text);
186	  border-color: var(--border-line-hover);
187	}
188	
189	.chevron {
190	  width: 12px;
191	  height: 12px;
192	  transition: transform var(--transition-fast);
193	}
194	.chevronOpen {
195	  transform: rotate(180deg);
196	}
197	
198	/* When expanded, the toggle sits floating to the right of the
199	   letter groups so it's still reachable. */
200	.collapseRow {
201	  display: flex;
202	  justify-content: flex-end;
203	}
204	
205	@media (max-width: 600px) {
206	  .letterGroup {
207	    flex-direction: column;
208	    gap: 6px;
209	  }
210	  .letter {
211	    width: auto;
212	  }
213	}
